1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
3	const BLOCK_SIZE = 3;
4	const BLOCK_DISCOUNT_PERCENT = 20;
5	const CURSE_SURCHARGE_PERCENT = 50;
6	const HIGH_ENCHANTMENT_THRESHOLD = 5;
7	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
8	const LOYALTY_YEARS_THRESHOLD = 2;
9	const LOYALTY_DISCOUNT_PERCENT = 20;
10	const FOLLOW_UP_DISCOUNT_PERCENT = 15;
11	const DEDUCTIBLE = 100;
12	const CAP_MULTIPLE = 2;
13	// The CLAIM_ prefix marks the claim-side pair. Both are deliberately distinct
14	// from their premium-side namesakes above: a sword can be enchanted enough to
15	// cost more to insure (threshold 5) without being enchanted enough to pay out
16	// less (threshold 8).
17	const CLAIM_HIGH_ENCHANTMENT_THRESHOLD = 8;
18	const CLAIM_HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT = 50;
19	
20	const BASE_PREMIUMS = {
21	  sword: 100,
22	  amulet: 60,
23	  staff: 80,
24	  potion: 40,
25	  rune: 25,
26	  moonstone: 25,
27	} as const;
28	
29	// What an item is insured FOR, as opposed to what insuring it costs. The cap on
30	// claims is derived from these, so premium discounts never move it.
31	const INSURANCE_VALUES = {
32	  sword: 1000,
33	  amulet: 600,
34	  staff: 800,
35	  potion: 400,
36	  rune: 250,
37	  moonstone: 250,
38	} as const;
39	
40	// The six priced types are the domain, so they are derived from the premium
41	// table rather than restated: a type nobody prices cannot be insured. The
42	// unknown-type case (broomstick) is still a runtime error the tests will drive.
43	type ItemType = keyof typeof BASE_PREMIUMS;
44	
45	// Components (as opposed to main items) are the only things the block rule
46	// applies to, so the distinction has to be data, not a price coincidence.
47	// Typed as a set of ItemType so a component can never name an unpriced type.
48	const COMPONENT_TYPES = new Set<ItemType>(["rune", "moonstone"]);
49	
50	const PERCENT_WHOLE = 100;
51	
52	// Divides rather than multiplying by a rate: `amount * 1.1` introduces
53	// floating-point error that shifts the spec's round-up in MHPCO's favour.
54	const percentOf = (percent: number, amount: number): number =>
55	  (amount * percent) / PERCENT_WHOLE;
56	
57	// MHPCO rounds every money amount in its own favour: premiums (customer pays)
58	// round up, payouts (MHPCO pays) round down.
59	const roundPremiumInMHPCOsFavour = Math.ceil;
60	
61	export type QuoteResult = { premium: number };
62	
63	export type ClaimResult = { payout: number; remainingCap: number };
64	
65	export type ScenarioResult = QuoteResult | ClaimResult;
66	
67	// `material` is accepted but never read: the dragon-material clause reimburses
68	// in full, which is what every ordinary item already gets, so no code can yet
69	// tell dragon from steel. See `reimbursableAmountFor`. All three are optional so
70	// a bare `{ type: "rune" }` typechecks: a rune has no enchantment to speak of,
71	// rather than an enchantment of zero.
72	type Item = {
73	  type: ItemType;
74	  material?: string;
75	  enchantment?: number;
76	  cursed?: boolean;
77	};
78	
79	type Damage = { itemType: string; amount: number };
80	
81	type Incident = { cause: string; damages: Damage[] };
82	
83	type QuoteStep = { op: "quote"; items: Item[] };
84	
85	type ClaimStep = { op: "claim"; policy: number; incident: Incident };
86	
87	type Step = QuoteStep | ClaimStep;
88	
89	const isQuote = (step: Step): step is QuoteStep => step.op === "quote";
90	
91	type Customer = { yearsWithMHPCO: number };
92	
93	type Scenario = {
94	  customer: Customer;
95	  steps: Step[];
96	};
97	
98	const sum = (amounts: number[]): number =>
99	  amounts.reduce((total, amount) => total + amount, 0);
100	
101	const basePremiumForItem = (item: Item): number => BASE_PREMIUMS[item.type];
102	
103	const sumBasePremiums = (items: Item[]): number => sum(items.map(basePremiumForItem));
104	
105	// Groups of items that are "alike" — same type. The type is kept alongside the
106	// items because the block rule asks about it; recovering it from items[0] would
107	// make every reader re-derive that a group is non-empty and homogeneous.
108	type AlikeItems = { type: ItemType; items: Item[] };
109	
110	const groupByType = (items: Item[]): AlikeItems[] => {
111	  const groups = new Map<ItemType, Item[]>();
112	  for (const item of items) {
113	    const group = groups.get(item.type) ?? [];
114	    group.push(item);
115	    groups.set(item.type, group);
116	  }
117	  return [...groups].map(([type, groupedItems]) => ({ type, items: groupedItems }));
118	};
119	
120	// A block is a discount on the components' combined base premium, not a flat
121	// price: 3 runes are 75 G less 20 % = 60 G. Derived rather than hardcoded so the
122	// 20 % stays visible as the rule it is.
123	const blockBasePremium = (items: Item[]): number => {
124	  const undiscounted = sumBasePremiums(items);
125	  return undiscounted - percentOf(BLOCK_DISCOUNT_PERCENT, undiscounted);
126	};
127	
128	// Exactly BLOCK_SIZE, not "at least": 4 or 7 runes form no block, so a bigger
129	// pile is never cheaper than the block it contains. Components only — three
130	// swords are three separate insurances, not a discounted building block.
131	const formsABlock = ({ type, items }: AlikeItems): boolean =>
132	  items.length === BLOCK_SIZE && COMPONENT_TYPES.has(type);
133	
134	const basePremiumForGroup = (alikeItems: AlikeItems): number =>
135	  formsABlock(alikeItems)
136	    ? blockBasePremium(alikeItems.items)
137	    : sumBasePremiums(alikeItems.items);
138	
139	// Priced per group of alike items rather than over the whole list, so 3 runes
140	// and 3 moonstones each form their own block.
141	const policyBasePremiumFor = (items: Item[]): number =>
142	  sum(groupByType(items).map(basePremiumForGroup));
143	
144	const percentOfWhen = (applies: boolean, percent: number, amount: number): number =>
145	  applies ? percentOf(percent, amount) : 0;
146	
147	// Each item-specific surcharge is a percentage of the affected item's OWN base
148	// premium, so every rule reads as "this much, when this holds". The terms are
149	// summed rather than chosen between: an item can trigger several at once.
150	//
151	// Deliberately two explicit terms rather than a table of rules. The shared
152	// shape is only the arithmetic tail; the conditions differ in kind (a flag vs.
153	// a threshold over an optional number), and nothing in the remaining spec adds
154	// a third item-specific surcharge to generalise over.
155	const surchargeFor = (item: Item): number => {
156	  const base = basePremiumForItem(item);
157	  return (
158	    percentOfWhen(item.cursed === true, CURSE_SURCHARGE_PERCENT, base) +
159	    percentOfWhen(
160	      (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
161	      HIGH_ENCHANTMENT_SURCHARGE_PERCENT,
162	      base,
163	    )
164	  );
165	};
166	
167	// Charged alongside the policy base premium — never folded into it, or the
168	// policy-wide modifiers would compound on top of them.
169	const itemSurchargesFor = (items: Item[]): number => sum(items.map(surchargeFor));
170	
171	// Unlike the item-specific surcharges, these are percentages of the WHOLE
172	// policy's base premium. Each is returned already signed — a surcharge is
173	// positive, a discount negative — so the rule and its direction stay on one
174	// line instead of the sign living in a `+`/`-` further down the sum.
175	const policyModifiersFor = (
176	  policyBasePremium: number,
177	  customer: Customer,
178	  isFollowUpContract: boolean,
179	): number[] => [
180	  // Applies to every quote, follow-ups included: the spec treats each item in a
181	  // quote as newly insured, regardless of how long the customer has been around.
182	  percentOf(FIRST_INSURANCE_SURCHARGE_PERCENT, policyBasePremium),
183	  -percentOfWhen(
184	    customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
185	    LOYALTY_DISCOUNT_PERCENT,
186	    policyBasePremium,
187	  ),
188	  -percentOfWhen(isFollowUpContract, FOLLOW_UP_DISCOUNT_PERCENT, policyBasePremium),
189	];
190	
191	// The order of the terms is the order of the spec's rules: what the items are
192	// worth, what they individually cost extra, what the policy as a whole is
193	// adjusted by, and MHPCO's fee on top.
194	const quoteFor = (
195	  items: Item[],
196	  customer: Customer,
197	  isFollowUpContract: boolean,
198	): QuoteResult => {
199	  const policyBasePremium = policyBasePremiumFor(items);
200	  const premium = roundPremiumInMHPCOsFavour(
201	    policyBasePremium +
202	      itemSurchargesFor(items) +
203	      sum(policyModifiersFor(policyBasePremium, customer, isFollowUpContract)) +
204	      PROCESSING_FEE,
205	  );
206	  return { premium };
207	};
208	
209	// A follow-up contract is any quote after the customer's first, so what counts
210	// is how many QUOTES precede this step — not how many steps do. Claim steps sit
211	// in the same list and must not push a later quote into follow-up territory.
212	const isFollowUpContract = (precedingSteps: Step[]): boolean =>
213	  precedingSteps.some(isQuote);
214	
215	const insuranceSumFor = (items: Item[]): number =>
216	  sum(items.map((item) => INSURANCE_VALUES[item.type]));
217	
218	// MHPCO pays, so payouts round down.
219	const roundPayoutInMHPCOsFavour = Math.floor;
220	
221	// How much of a damage the policy reimburses, before the deductible. The
222	// clauses are CHOSEN BETWEEN, not summed — unlike the premium surcharges, where
223	// a cursed AND highly-enchanted sword pays both. Written as a chain of
224	// exceptions over a default so precedence is the reading order: the first
225	// matching clause wins.
226	//
227	// Only one exception is listed. Dragon material is the spec's other clause, but
228	// it reimburses in full, which is already the default — so it is deliberately
229	// absent rather than written as a branch returning `damage.amount` unchanged.
230	// A conditional whose arms agree hides that agreement instead of stating it,
231	// and suggests the material is doing work here when it is not. It earns a
232	// branch on the day a test makes dragon differ from ordinary steel.
233	const reimbursableAmountFor = (damage: Damage, damagedItem: Item): number =>
234	  (damagedItem.enchantment ?? 0) >= CLAIM_HIGH_ENCHANTMENT_THRESHOLD
235	    ? percentOf(CLAIM_HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT, damage.amount)
236	    : damage.amount;
237	
238	// Each damage entry carries its own deductible: one dragon attack damaging two
239	// items is two damages, and MHPCO withholds 100 G from each. The reimbursement
240	// clauses apply to the damage amount FIRST, so the deductible bites last.
241	const payoutForDamage = (damage: Damage, damagedItem: Item): number =>
242	  reimbursableAmountFor(damage, damagedItem) - DEDUCTIBLE;
243	
244	// Which insured item a damage entry refers to, since the reimbursement clauses
245	// depend on that item's enchantment and material. Nothing validates that the
246	// policy actually covers the damaged type yet; the error-case tests will turn
247	// this throw into a reported error.
248	const damagedItemFor = (damage: Damage, insuredItems: Item[]): Item => {
249	  const item = insuredItems.find((insured) => insured.type === damage.itemType);
250	  if (item === undefined) {
251	    throw new Error(`Claim damages a ${damage.itemType}, which this policy does not cover`);
252	  }
253	  return item;
254	};
255	
256	// The cap is a property of the POLICY, not of the claim: twice what the policy's
257	// items are insured for. Kept separate from the payout so the cross-claim
258	// accumulation the spec still demands has an obvious place to attach.
259	const capFor = (policy: QuoteStep): number =>
260	  insuranceSumFor(policy.items) * CAP_MULTIPLE;
261	
262	// The cap is spent down across every claim on a policy rather than reset per
263	// claim, so the caller supplies what is left; a claim wanting more than remains
264	// is cut short by it.
265	const claimFor = (claim: ClaimStep, policy: QuoteStep, capRemaining: number): ClaimResult => {
266	  const desired = roundPayoutInMHPCOsFavour(
267	    sum(
268	      claim.incident.damages.map((damage) =>
269	        payoutForDamage(damage, damagedItemFor(damage, policy.items)),
270	      ),
271	    ),
272	  );
273	  const payout = Math.min(desired, capRemaining);
274	  return { payout, remainingCap: capRemaining - payout };
275	};
276	
277	// `claim.policy` indexes the scenario's steps, and the referenced step must be a
278	// quote — a claim against a claim is meaningless. Nothing validates the scenario
279	// yet, so this states the assumption instead of casting past it; the
280	// error-case tests will turn the throw into a reported error.
281	const policyReferencedBy = (claim: ClaimStep, steps: Step[]): QuoteStep => {
282	  const step = steps[claim.policy];
283	  if (step === undefined || !isQuote(step)) {
284	    throw new Error(`Claim references step ${claim.policy}, which is not a quote`);
285	  }
286	  return step;
287	};
288	
289	// Steps are processed in order because claims consume a policy's cap: what a
290	// later claim can pay depends on what earlier ones already took, so the
291	// remaining cap per policy is carried along rather than recomputed.
292	export const runScenario = (scenario: Scenario): { results: ScenarioResult[] } => {
293	  const capRemainingByPolicy = new Map<number, number>();
294	  const results = scenario.steps.map((step, stepIndex) => {
295	    if (isQuote(step)) {
296	      return quoteFor(
297	        step.items,
298	        scenario.customer,
299	        isFollowUpContract(scenario.steps.slice(0, stepIndex)),
300	      );
301	    }
302	    const policy = policyReferencedBy(step, scenario.steps);
303	    const capRemaining = capRemainingByPolicy.get(step.policy) ?? capFor(policy);
304	    const result = claimFor(step, policy, capRemaining);
305	    capRemainingByPolicy.set(step.policy, result.remainingCap);
306	    return result;
307	  });
308	  return { results };
309	};
