// Steps are processed in order because claims consume a policy's cap: what a
// later claim can pay depends on what earlier ones already took, so the
// remaining cap per policy is carried along rather than recomputed.
export const runScenario = (scenario: Scenario): { results: ScenarioResult[] } => {
  const capRemainingByPolicy = new Map<number, number>();
  const results = scenario.steps.map((step, stepIndex) => {
    if (isQuote(step)) {
      return quoteFor(
        step.items,
        scenario.customer,
        isFollowUpContract(scenario.steps.slice(0, stepIndex)),
      );
    }
    const policy = policyReferencedBy(step, scenario.steps);
    const capRemaining = capRemainingByPolicy.get(step.policy) ?? capFor(policy);
    const result = claimFor(step, policy, capRemaining);
    capRemainingByPolicy.set(step.policy, result.remainingCap);
    return result;
  });
  return { results };
};

